test("exactly 30 calendar days is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("29 calendar days is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-06-30" }), { accepted: false, daysUntilExpiry: 29 });
});
test("one day above the 30-day threshold is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-07-02" }), { accepted: true, daysUntilExpiry: 31 });
});
test("non-leap month-end span of exactly 30 days is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-31", expiryDate: "2026-03-02" }), { accepted: true, daysUntilExpiry: 30 });
});
test("one day below the non-leap month-end span is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-31", expiryDate: "2026-03-01" }), { accepted: false, daysUntilExpiry: 29 });
});
test("one day above the non-leap month-end span is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-01-31", expiryDate: "2026-03-03" }), { accepted: true, daysUntilExpiry: 31 });
});
test("first day of a 31-day month to its last day is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-03-01", expiryDate: "2026-03-31" }), { accepted: true, daysUntilExpiry: 30 });
});
test("first day to the day before month end is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-03-01", expiryDate: "2026-03-30" }), { accepted: false, daysUntilExpiry: 29 });
});
test("December 31 to January 30 crosses the year and is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-31", expiryDate: "2027-01-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("December 31 to January 29 is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-31", expiryDate: "2027-01-29" }), { accepted: false, daysUntilExpiry: 29 });
});
test("December 1 to December 31 is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-12-01", expiryDate: "2026-12-31" }), { accepted: true, daysUntilExpiry: 30 });
});
test("leap day to 30 days later is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-30" }), { accepted: true, daysUntilExpiry: 30 });
});
test("leap day to 29 days later is rejected", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-29", expiryDate: "2024-03-29" }), { accepted: false, daysUntilExpiry: 29 });
});
test("day before leap day counting the leap day is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-02-28", expiryDate: "2024-03-29" }), { accepted: true, daysUntilExpiry: 30 });
});
test("January 31 in a leap year to March 1 is accepted", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2024-01-31", expiryDate: "2024-03-01" }), { accepted: true, daysUntilExpiry: 30 });
});
test("longer unequal span is accepted with 75 days left", function () {
  assert.deepEqual(code.checkIdentityDocument({ checkDate: "2026-06-01", expiryDate: "2026-08-15" }), { accepted: true, daysUntilExpiry: 75 });
});
